def digest(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()

def apply_text(text):
    text = text.replace("\r\n", "\n")
    found = digest(text)
    if found == RESULT_TEXT_SHA256:
        return text, False
    if found != BASELINE_TEXT_SHA256:
        raise ValueError("SD wrapper differs from the manifest baseline and this integration; preserve it and inspect its changes. SHA256=" + found)
    lines = text.splitlines(keepends=True)
    for edit in reversed(EDITS):
        start, end = edit["start"], edit["end"]
        if lines[start:end] != edit["old"]:
            raise ValueError("Baseline context mismatch at line " + str(start + 1))
        lines[start:end] = edit["new"]
    result = "".join(lines)
    if digest(result) != RESULT_TEXT_SHA256:
        raise ValueError("Internal patch result hash mismatch")
    return result, True

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=pathlib.Path, default=pathlib.Path(__file__).resolve().parents[1])
    parser.add_argument("--file", type=pathlib.Path, help="An explicitly restored SD-wrapper copy, for reconstruction checks")
    parser.add_argument("--check", action="store_true", help="Validate applicability without writing")
    args = parser.parse_args()
    path = args.file or args.root / "rtl/SD/sd_card_bmp.v"
    raw = path.read_bytes()
    result, changed = apply_text(raw.decode("utf-8"))
    if changed and not args.check:
        path.write_bytes(result.encode("utf-8"))
    print(json.dumps({"path": str(path), "state": "APPLICABLE" if changed and args.check else "APPLIED" if changed else "UNCHANGED", "before_sha256": hashlib.sha256(raw).hexdigest(), "result_text_sha256": digest(result), "baseline_manifest_sha256": BASELINE_SHA256, "edit_count": len(EDITS)}))

if __name__ == "__main__":
    main()
